public boolean avaCheckCustomer()
{
    CustTable custTable = CustTable::find(this.CustAccount);

    if (!custTable.AVAIsCreditLimitRiscDebtor() && custTable.AVACreditLimitCustGroup())
    {
        return checkFailed(strFmt("@NDX:NXACustomerIsMemberOfCRLGroup", this.CustAccount, custTable.AVACreditLimitCustGroup()));
    }

    return true;
}

public boolean validateWrite()
{
    boolean ret;
    ret = next validateWrite() && this.avaCheckCustomer();

    return ret;
}
